<?php  use App\Models\User; use Illuminate\Support\Facades\Hash;  beforeEach(function () {     $this->admin = User::factory()->create([         'role' => 'admin',         'status' => 'aktif',     ]); });  test('admin can view users list', function () {     $user = User::factory()->create([         'username' => 'testuser1',         'email' => 'test1@example.com',         'role' => 'donatur',     ]);      $response = $this->actingAs($this->admin)->get(route('users.index'));      $response->assertOk();     $response->assertSee('testuser1'); });  test('admin can filter users by role', function () {     User::factory()->create([         'username' => 'donaturuser',         'role' => 'donatur',     ]);     User::factory()->create([         'username' => 'bendaharauser',         'role' => 'bendahara',     ]);      $response = $this->actingAs($this->admin)->get(route('users.index', ['role' => 'bendahara']));      $response->assertOk();     $response->assertSee('bendaharauser');     $response->assertDontSee('donaturuser'); });  test('admin can search users by username or email', function () {     User::factory()->create([         'username' => 'carisaya',         'email' => 'carisaya@example.com',     ]);     User::factory()->create([         'username' => 'janganlihat',         'email' => 'sembunyi@example.com',     ]);      $response = $this->actingAs($this->admin)->get(route('users.index', ['search' => 'carisaya']));      $response->assertOk();     $response->assertSee('carisaya');     $response->assertDontSee('janganlihat'); });  test('admin can view user edit page', function () {     $user = User::factory()->create();      $response = $this->actingAs($this->admin)->get(route('users.edit', $user));      $response->assertOk();     $response->assertSee($user->username); });  test('admin can update user account information', function () {     $user = User::factory()->create([         'username' => 'userlama',         'email' => 'userlama@example.com',         'role' => 'donatur',         'status' => 'aktif',     ]);      $response = $this->actingAs($this->admin)->patch(route('users.update', $user), [         'username' => 'userbaru',         'email' => 'userbaru@example.com',         'role' => 'bendahara',         'status' => 'tidak_aktif',     ]);      $response->assertRedirect(route('users.index'));     $response->assertSessionHas('success');      $this->assertDatabaseHas('users', [         'id' => $user->id,         'username' => 'userbaru',         'email' => 'userbaru@example.com',         'role' => 'bendahara',         'status' => 'tidak_aktif',     ]); });  test('admin can update user password', function () {     $user = User::factory()->create([         'role' => 'donatur',         'status' => 'aktif',     ]);      $response = $this->actingAs($this->admin)->patch(route('users.update', $user), [         'username' => $user->username,         'email' => $user->email,         'role' => 'donatur',         'status' => 'aktif',         'password' => 'newpassword123',         'password_confirmation' => 'newpassword123',     ]);      $response->assertRedirect(route('users.index'));     $response->assertSessionHas('success');      $this->assertTrue(Hash::check('newpassword123', $user->fresh()->password)); });  test('admin can toggle user status', function () {     $user = User::factory()->create([         'status' => 'aktif',     ]);      $response = $this->actingAs($this->admin)->patch(route('users.toggle-status', $user));      $response->assertSessionHas('success');     expect($user->fresh()->status)->toBe('tidak_aktif');      $this->actingAs($this->admin)->patch(route('users.toggle-status', $user));     expect($user->fresh()->status)->toBe('aktif'); });